pragma solidity >=0.8.0;

contract Child {
    uint256 public hits;
    uint256 public lastResult;

    function f(uint256 x) public returns (uint256) {
        hits = x + 1;
        return 200 + x;
    }

    function f(uint256 x, uint256 y) public returns (uint256) {
        lastResult = 300 + x + y;
        return lastResult;
    }

    function g(uint256 x) public returns (uint256) {
        lastResult = this.f(x);
        return lastResult;
    }
}
